UPDATE talk_parts SET sort_order = 1, phase = 'OPENING + IDENTIFY', row_name = 'Say hi + the hook + Problem definition', goal = 'Clear definition of the problem', core_values = 0, speaker = 'Isla', say = '["Hi! We are the Rooted Warriors from Flagstaff, Arizona.","(Everyone says their own name, down the line.)","Imagine driving on I-17 at night when an elk steps onto the road. So we built a wildlife camera that shows where animals really cross.","Here is our problem. Nate Reagan from Arizona Game and Fish told us I-17 has about 300 animal strikes a year. That is almost one crash every single day.","A new 24-million-dollar wildlife bridge at Willard Springs should cut those crashes by 90 percent.","But Game and Fish might only put one camera on it, and we won''t get their data. So how will anyone know if animals really use it?"]', show_what = 'Whole team standing together, trifold behind you · then: Problem section of the trifold', photos = '[]', check_note = 'The notebook never wrote down a one-sentence problem statement. This is a draft from your Nate notes: change it into your own words.' WHERE id = 1 AND talk = 'ip';
UPDATE talk_parts SET sort_order = 2, phase = 'IDENTIFY + DESIGN', row_name = 'Research + Project plan', goal = 'Clear, detailed research from a variety of sources · Clear evidence of an effective project plan', core_values = 1, speaker = 'Adeline', say = '["We used more than one source.","We interviewed an expert, Nate Reagan, with five questions we wrote. He said Game and Fish uses GPS collars, live-stream cameras and thermal goggles, but not much AI.","We also used Google Gemini to compare computers, and learned a Raspberry Pi uses too much battery and cannot sleep.","Then we made a project plan as a Gantt chart in our team app.","Every task has an owner and dates, from picking the design to practicing this talk.","We started October 2."]', show_what = 'Expert notes / question list · then: Gantt chart (app, Innovation Project page, printed or on the trifold)', photos = '[]', check_note = 'Only 2 research sources are logged (Gemini Oct 3, Nate Oct 5). "A variety of sources" scores higher: add any website, article, book or video you used.' WHERE id = 3 AND talk = 'ip';
UPDATE talk_parts SET sort_order = 3, phase = 'DESIGN + CREATE', row_name = 'Team involvement + Innovation', goal = 'Clear evidence that development involved all team members · Detailed explanation of innovation in the solution', core_values = 1, speaker = 'Thea', say = '["Everybody had a job.","I led the design and programmed the camera. Nolan wired it with my help, and Nolan and Weston soldered it.","Adeline and I kept our expert notes and made the trifold. Isla [[what Isla did]], and Fynn [[what Fynn did]].","So what is new? Our camera is tiny, cheap and smart.","It only saves a picture when the picture changes or the motion sensor fires, then sends it over its own Wi-Fi to our Raspberry Pi.","The Pi''s AI, SpeciesNet, names the animal with no internet, and blurs out any people."]', show_what = 'Soldering photos · then: Pi Camera Station touchscreen', photos = '["11-1-soldering-2.jpg"]', check_note = 'The notebook has no Innovation Project job logged for Isla or Fynn. Judges score "all team members" here, so fill the yellow part with something true (testing the camera, research, the trifold, practicing the talk…).' WHERE id = 5 AND talk = 'ip';
UPDATE talk_parts SET sort_order = 4, phase = 'CREATE + ITERATE', row_name = 'Model / drawing + Sharing', goal = 'Detailed model/drawing that represents the solution · Solution shared with multiple people/groups', core_values = 0, speaker = 'Nolan', say = '["This is our real camera.","Inside: a Seeed XIAO ESP32-S3 Sense board, a motion sensor, a clock and a mode switch.","Our wiring diagram shows every wire. It runs on USB-C, from a phone charger or our solar box.","On October 5 we shared our idea with Nate Reagan from Arizona Game and Fish.","He told us not to live stream, and that cameras spread out over a wide area work best.","We also showed it to [[who else? family, teachers, a class, another team]]."]', show_what = 'The real camera + wiring diagram (app, Innovation Project Details) · then: Communication table (app, Innovation Project page)', photos = '["11-1-soldering-1.jpg"]', check_note = 'Only ONE sharing is logged (Nate). "Accomplished" needs MULTIPLE people or groups. Before Saturday: show it to family, a teacher or a class, and say what they said.' WHERE id = 7 AND talk = 'ip';
UPDATE talk_parts SET sort_order = 5, phase = 'ITERATE + COMMUNICATE', row_name = 'Improvements + Explanation & impact', goal = 'Clear evidence of improvements based on feedback · Clear explanation of solution and its impact on others', core_values = 1, speaker = 'Weston', say = '["Feedback changed our design.","Our first plan put a Raspberry Pi in the forest. After our research, we switched to the tiny camera.","Because of Nate, we don''t live stream: the Pi blurs people, and we check every photo before sharing.","Here is how it all works together: animal, camera, Pi, AI, and then we choose what to share.","We can''t get Game and Fish''s data, so we collect our own.","Knowing where animals cross helps put crossings in the right places: fewer crashes for animals and drivers."]', show_what = 'Before → after on the trifold (Pi in the forest → tiny camera) · then: Point along the path on the trifold: camera → Pi → AI → us', photos = '[]', check_note = NULL WHERE id = 9 AND talk = 'ip';
UPDATE talk_parts SET sort_order = 6, phase = 'COMMUNICATE + CLOSING', row_name = 'Pride & enthusiasm + Next steps + thank you', goal = 'Presentation clearly shows pride or enthusiasm', core_values = 1, speaker = 'Fynn', say = '["We are so proud!","We built two cameras and did real soldering. On November 9 the whole system worked for the first time: camera, to Pi, to AI!","It only found people waving, because we tested indoors. Next, it goes outside to find real animals.","Next, we''ll fix our second camera, put one outside facing the forest, and ask ADOT about a wildlife bridge.","Thank you! Do you have any questions for us?","(Everyone:) We are the Rooted Warriors!"]', show_what = 'Big smiles. Hold up the camera. · then: Everyone together', photos = '[]', check_note = NULL WHERE id = 11 AND talk = 'ip';
DELETE FROM talk_parts WHERE talk = 'ip' AND id IN (2, 4, 6, 8, 10, 12);
